assert (R/'alias_correction.json').exists() and not(R/'corrected_evaluation.json').exists();old=json.loads((R/'first_calculation_report.json').read_text());plan=json.loads((R/'plan.json').read_text());batch=json.loads((R/'batch.json').read_text());corrected=json.loads((R/'corrected_batch.json').read_text());records=reg.read_records(ROOT/'research/automation/registry.jsonl');assert len(corrected)==24 and all(records[x['fingerprint']]['status']=='reserved' for x in batch);started=now();_,markets,common,vectors,ss=parent.recover(plan);newnames={x['name'] for x in corrected};configs={n:copy.deepcopy(c) for n,c in old['configs'].items() if n not in newnames};assert len(configs)==14
